function isEHData(n, m1, m2, unit):
    for x in 0..n-1:
        if m1(unit,x) != x or m1(x,unit) != x: return false
        if m2(unit,x) != x or m2(x,unit) != x: return false
    for a in 0..n-1:
      for b in 0..n-1:
        for c in 0..n-1:
          for d in 0..n-1:
            lhs = m1(m2(a,b), m2(c,d))
            rhs = m2(m1(a,c), m1(b,d))
            if lhs != rhs: return false
    return true

