    return EHData(n, m1=mul, m2=mul, unit=one)   # interchange = medial law

function toCommMonoid(E):
    assert isEHData(E.n, E.m1, E.m2, E.unit)
    return (E.n, E.m1, E.unit)                   # (carrier, mult, identity)

function roundTrip(n, mul, one):
    E = ofCommMonoid(n, mul, one)
    (n2, mul2, one2) = toCommMonoid(E)
    assert mul2 == mul and one2 == one

